"""
The loader for .txt and .md files.

Who calls it: ingest_file() in ingestion/pipeline.py (ticket #34). It gets the
file name and the raw bytes from POST /upload and passes them on.

What it hands on: ONE Document with ONE Section that holds the whole text.
The chunker (ticket #25) cuts that Section into chunks.

It takes bytes and not a path, because that is what POST /upload receives.
"""

from pathlib import PurePath

from study_buddy.models import Document, Section

# The only suffixes this loader understands. PDF and YouTube get their own
# loaders later, and a router (phase 2) will pick the right one.
SUPPORTED_SUFFIXES = {"txt", "md"}


def load_text_file(filename: str, data: bytes) -> Document:
    """
    Turn the name and the bytes of a .txt or .md file into a Document.

    Raises ValueError if the suffix is not .txt or .md, if the bytes are not
    valid UTF-8, or if the file is empty. /upload can turn that into a 400 later.
    """
    # 1. Find the suffix and lowercase it: "Notes.MD" -> "md".
    #    Document.source_type only accepts the exact lowercase words.
    suffix = PurePath(filename).suffix.lower().removeprefix(".")

    # 2. This loader never guesses. Anything else is refused.
    if suffix not in SUPPORTED_SUFFIXES:
        raise ValueError(
            f"Cannot load '{filename}': expected a .txt or .md file, "
            f"got suffix '{suffix}'."
        )

    # 3. Bytes -> text. Silent replacement characters would give bad chunks
    #    and nobody would notice, so we fail loudly instead.
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as err:
        raise ValueError(f"Cannot load '{filename}': not valid UTF-8.") from err

    # 4. An empty file would give zero chunks, and a document with no chunks
    #    has nothing to find later.
    if not text.strip():
        raise ValueError(f"Cannot load '{filename}': the file is empty.")

    # 5. Windows saves a new line as \r\n. The chunker splits on "\n\n",
    #    which would not match "\r\n\r\n", so we turn \r\n into \n here.
    text = text.replace("\r\n", "\n")

    # 6. One Section for the whole file. A .txt or .md has no page or second,
    #    so source_location stays None.
    return Document(
        filename=filename,
        source_type=suffix,
        sections=[Section(text=text)],
    )
